function routeFixture({source='COMPANY',fallbackCompany=false,forgeCallerFlag=false}={}){
 const time=Date.now(),row={id:'customer_webhook_'+digest('private-route-memory'),projectId:'project-a',payload:{organizationId:'org-a',channelId:'channel-a',payloadDigest:'b'.repeat(64)},status:'PENDING',leaseToken:null,leaseExpiresAt:null,attempts:0,outcome:null},calls=[],contexts=[],configuration={source,fallbackCompany,failOnce:false};
 const query=async(sql,args=[])=>{
  if(['BEGIN','COMMIT','ROLLBACK'].includes(sql)||sql.startsWith('SET LOCAL'))return {rows:[],rowCount:0};
  if(sql.startsWith('SELECT c.*,p."organizationId"'))return {rows:[{metadata:{}}],rowCount:1};
  if(sql==='SELECT clock_timestamp() AS now')return {rows:[{now:new Date(time)}],rowCount:1};
  if(sql.startsWith('SELECT id,')&&sql.includes('FROM public."WebhookEvent"'))return {rows:sql.includes("provider='meta-customer-outbound-v1'")?[]:[structuredClone(row)],rowCount:1};
  if(sql.startsWith('UPDATE public."WebhookEvent" SET "leaseToken"')){row.leaseToken=args[1];row.leaseExpiresAt=args[2];row.attempts++;return {rows:[],rowCount:1};}
  if(sql.startsWith('UPDATE public."WebhookEvent" SET status=\'PROCESSED\'')){assert.equal(row.leaseToken,args[2]);row.status='PROCESSED';row.outcome=JSON.parse(args[3]);row.leaseToken=null;row.leaseExpiresAt=null;return {rows:[],rowCount:1};}
  if(sql.startsWith('UPDATE public."WebhookEvent" SET "lastError"')){row.lastError=args[2];row.leaseToken=null;row.leaseExpiresAt=null;return {rows:[],rowCount:1};}
  throw Error('Unexpected route-only memory SQL '+sql);
 };
 const result=kind=>({kind,identityStatus:'SYNTHETIC_ROUTING_ONLY',businessApplied:false,reply:{type:'text',body:'Synthetic routing-only prompt'}});
 const execute=lane=>async context=>{calls.push(lane);contexts.push(context);if(forgeCallerFlag)Object.assign(context,{companyResults:true,companyResult:true,companyBridgeProducedResult:true,isCompany:true});return configuration.source===lane?result(lane==='INTAKE'?'EMPLOYEE_INTAKE':lane==='KYC'?'KYC_CHAT':'CONVERSATION'):null;};
 const send=lane=>async()=>{calls.push(lane+'-SEND');if(configuration.failOnce){configuration.failOnce=false;throw new WorkspaceError('META_CUSTOMER_INBOX_LEASE_CHANGED',409);}return {state:'SENT',replySent:true};};
 const none=async()=>null,processor=createMetaCustomerProductionProcessor({connect:async()=>({query,release(){}}),now:()=>time,environment:{},onboarding:null,fieldBridge:{execute:execute('FIELD')},kycBridge:{executeIntake:execute('INTAKE'),execute:execute('KYC')},kycOutbound:{send:send('KYC')},appProjection:{execute:execute('APP')},companyBridge:{execute:execute('COMPANY')},fieldOutbound:{send:send('FIELD'),observeStatus:none},companyOutbound:{send:send('COMPANY')},isCompany:async()=>{calls.push('IS-COMPANY');return configuration.fallbackCompany;},rejectedKyc:{rejection:none,send:send('REJECTION')},expiredKyc:{feedback:none,send:send('EXPIRY')},contextKyc:{feedback:none,send:send('CONTEXT')},deferAuthorization:async()=>false,authorizationCodes:[]});
 return {row,calls,contexts,configuration,processor};
}
