function expireAndCorruptRecovery(r){r.f.advance(130000);reclaimSource(r);r.f.worker.metadata.fieldConsumptionRecovery.encryptedState='corrupt-private-recovery';r.f.worker.metadata.fieldChannelConversation.encryptedState='corrupt-private-conversation';const receipt=[...r.f.audits.values()].find(row=>row.metadata.eventId===r.event.id);receipt.metadata.encryptedResult='corrupt-private-dispatch';r.f.projections.get(r.event.id).encryptedResult='corrupt-private-company-cache';return receipt;}
test('pending expired same-source recovery sends only exact feedback with every private cache/draft body corrupt and no prior outbound marker',async()=>{
 const r=await composed({recovery:true,phase:'AFTER_BRIDGE_COMMIT'});assert.equal(r.posts.length,0);assert.equal(r.marker,undefined);const receipt=expireAndCorruptRecovery(r),before=structuredClone(receipt),sidecar=structuredClone(r.f.worker.metadata.fieldConsumptionRecovery),prompt=structuredClone(r.f.worker.metadata.fieldChannelConversation),projection=structuredClone(r.f.projections.get(r.event.id));
 const feedback=await r.company.execute(r.capturedContext);assert.equal(feedback.code,'META_CHANNEL_CONSUMPTION_RECOVERY_EXPIRED');assert.match(feedback.reply.body,/Venció el plazo/);assert.doesNotMatch(feedback.reply.body,/Cemento|2\.000|PRIVATE_REASON/);
 const sent=await r.lane.send(r.capturedContext,feedback.reply);assert.equal(sent.replySent,true);assert.equal(r.posts.length,1);assert.match(r.posts[0].body.text.body,/Venció el plazo/);assert.deepEqual(receipt,before);assert.deepEqual(r.f.worker.metadata.fieldConsumptionRecovery,sidecar);assert.deepEqual(r.f.worker.metadata.fieldChannelConversation,prompt);assert.deepEqual(r.f.projections.get(r.event.id),projection);
});
for(const state of ['SEND_STARTED','SEND_UNKNOWN','SENT','STATUS_OBSERVED'])test('expired feedback never resends or rewrites an existing '+state+' marker',async()=>{
 const r=await composed({recovery:true,phase:'FINAL_BEFORE_EXTERNAL'});assert.equal(r.posts.length,0);assert.ok(r.marker);expireAndCorruptRecovery(r);r.marker.outcome.state=state;const before=structuredClone(r.marker),feedback=await r.company.execute(r.capturedContext);const observed=await r.lane.send(r.capturedContext,feedback.reply);assert.equal(observed.state,state);assert.equal(observed.replySent,false);assert.equal(observed.observationOnly,true);assert.equal(observed.replayed,true);assert.equal(r.posts.length,0);assert.deepEqual(r.marker,before);
});
for(const phase of ['AFTER_BRIDGE_COMMIT','AFTER_RESERVE','FINAL_BEFORE_EXTERNAL'])test('a prepared private recovery summary crossing its deadline at '+phase+' is denied instead of being transformed or posted',async()=>{
 const r=await composed({recovery:true,phase,mutation:'EXPIRY'});assert.equal(r.posts.length,0);assert.ok(r.errors.length>0||r.outcome?.replySent===false);
});
test('an expired source with no live matching recovery header cannot assert that its data remains retained',async()=>{
 const r=await composed({recovery:true,phase:'AFTER_BRIDGE_COMMIT'});expireAndCorruptRecovery(r);delete r.f.worker.metadata.fieldConsumptionRecovery;await assert.rejects(r.company.execute(r.capturedContext),{code:'WORKER_CHANNEL_PERMISSION_REQUIRED'});assert.equal(r.posts.length,0);
});
for(const state of ['SEND_STARTED','SEND_UNKNOWN','SENT'])test('shared processor records an original '+state+' observation without claiming the derived expiry feedback was sent',async()=>{
 const r=await composed({recovery:true,phase:'FINAL_BEFORE_EXTERNAL'});assert.equal(r.posts.length,0);expireAndCorruptRecovery(r);r.marker.outcome.state=state;const marker=structuredClone(r.marker),source=r.f.events.get(r.event.id);Object.assign(source,{status:'PENDING',leaseToken:null,leaseExpiresAt:null,lastError:'SYNTHETIC_PRIOR_UNCERTAINTY'});const result=await r.processor.process(r.event.id);assert.equal(result.processed,true);assert.equal(result.replySent,false);assert.equal(result.replyState,state);assert.equal(result.replyObservation,'ORIGINAL_REPLY_OBSERVED');assert.equal(result.code,'META_CHANNEL_CONSUMPTION_RECOVERY_EXPIRED');assert.equal(source.lastError,'SYNTHETIC_PRIOR_UNCERTAINTY');assert.deepEqual(r.marker,marker);assert.equal(r.posts.length,0);
});
test('a recovery deadline crossed during the last marker read is caught by the final fresh database clock',async()=>{
 const r=await composed({recovery:true,phase:'AFTER_FINAL_RESERVATION_READ',mutation:'EXPIRY'});assert.equal(r.posts.length,0);assert.ok(r.outcome?.replySent===false||r.errors.length>0);assert.equal(r.marker.outcome.state,'SEND_STARTED');
});


test('legacy ADMIN readiness GETs finish before a fresh locked final reply and one POST',async()=>{
 const r=await composed({legacyAdmin:{}});assert.equal(r.errors.length,0);assert.equal(r.own.adminPreflight,true);assert.equal(Object.hasOwn(r.f.connection.metadata,'ownCompanyRuntime'),false);assert.equal(r.posts.length,1);assert.equal(r.posts[0].inTransaction,1);assert.ok(r.own.graph.length>0);assert.ok(r.own.graph.every(row=>row.inTransaction===0));assert.ok(r.own.graph.at(-1).path.endsWith('/phone_numbers'));assert.equal(r.fullResolverQueries,2);assert.equal(r.compactWorkerQueries,2);assert.equal(r.outcome.replySent,true);const finalQueries=r.outboundQueries.slice(r.own.graph.at(-1).sqlIndex-r.intercepted.length+r.outboundQueries.length);assert.ok(finalQueries.some(row=>row.sql.startsWith('WITH "workerChannelPrincipal"')));assert.match(r.posts[0].lastSql,/clock_timestamp\(\) AS now/);
});

for(const phase of ['LAST_READINESS_GET','FINAL_PROVIDER_CALLBACK'])for(const markerState of ['SEND_UNKNOWN','SENT','REJECTED','STATUS_OBSERVED'])test('legacy ADMIN '+phase+' observes terminal '+markerState+' without another POST or marker rewrite',async()=>{
 let observed,mutations=0;const change=({f,event})=>{mutations++;const marker=f.events.get(companyComposedOutboundId(event.id));marker.outcome={...marker.outcome,state:markerState};marker.leaseToken=null;observed=structuredClone(marker);};const config=phase==='LAST_READINESS_GET'?{afterGet:value=>{if(value.own.graph.at(-1).path.endsWith('/phone_numbers'))change(value);}}:{beforeFinalFence:change};const r=await composed({legacyAdmin:config});assert.equal(mutations,1);assert.equal(r.own.adminPreflight,true);assert.ok(r.own.graph.every(row=>row.inTransaction===0));assert.equal(r.posts.length,0);assert.deepEqual(r.marker,observed);assert.equal(r.outcome.replyState,markerState);assert.equal(r.outcome.replySent,false);assert.equal(r.errors.length,0);const snapshot=structuredClone(r.marker),source=r.f.events.get(r.event.id);Object.assign(source,{status:'PENDING',leaseToken:r.capturedContext.leaseToken,leaseExpiresAt:new Date(r.f.clock()+60000)});const replay=await r.lane.send(r.capturedContext,r.prepared.reply);assert.equal(replay.state,markerState);assert.equal(replay.replySent,markerState==='SENT'||markerState==='STATUS_OBSERVED');assert.equal(replay.replayed,true);assert.deepEqual(r.marker,snapshot);assert.equal(r.posts.length,0);
});

for(const phase of ['LAST_READINESS_GET','FINAL_PROVIDER_CALLBACK'])for(const change of ['lease','requestDigest'])test('legacy ADMIN '+phase+' denies foreign captured marker '+change+' without POST or changing its lease',async()=>{
 let observed,mutations=0;const mutate=({f,event})=>{mutations++;const marker=f.events.get(companyComposedOutboundId(event.id));if(change==='lease')marker.leaseToken='synthetic-foreign-admin-marker-lease';else marker.payload.requestDigest='e'.repeat(64);observed=structuredClone(marker);};const config=phase==='LAST_READINESS_GET'?{afterGet:value=>{if(value.own.graph.at(-1).path.endsWith('/phone_numbers'))mutate(value);}}:{beforeFinalFence:mutate};const r=await composed({legacyAdmin:config});assert.equal(mutations,1);assert.equal(r.own.adminPreflight,true);assert.ok(r.own.graph.every(row=>row.inTransaction===0));assert.equal(r.posts.length,0);assert.deepEqual(r.marker,observed);assert.equal(r.marker.outcome.state,'SEND_STARTED');assert.equal(r.outcome.replySent,false);
});

for(const mutation of ['REPORT','KYC','BINDING','MEMBERSHIP'])test('legacy ADMIN readiness completion revalidates '+mutation+' before the reply POST',async()=>{
 let changed=false;const r=await composed({mutation,legacyAdmin:{afterGet:value=>{if(value.own.graph.at(-1).path.endsWith('/phone_numbers')){changed=true;value.mutate();}}}});assert.equal(changed,true);assert.equal(r.own.adminPreflight,true);assert.equal(r.posts.length,0);const expectedCode={REPORT:'WORKER_CHANNEL_PERMISSION_REQUIRED',KYC:'WORKER_CHANNEL_BINDING_REQUIRED',BINDING:'COMPANY_CHANNEL_CONTEXT_CHANGED',MEMBERSHIP:'WORKER_CHANNEL_PARTICIPANT_REQUIRED'}[mutation];assert.ok(r.outcome?.replySent===false||r.errors.some(error=>error.code===expectedCode),JSON.stringify({mutation,codes:r.errors.map(error=>error.code),outcome:r.outcome?.replyState}));assert.ok(r.own.graph.every(row=>row.inTransaction===0));
});

for(const window of ['source','draft'])test('legacy ADMIN final marker await cannot freeze the '+window+' deadline before the private POST',async()=>{
 let crossed=false;const r=await composed({recovery:window==='draft',mutation:window==='draft'?'EXPIRY':'REPORT',legacyAdmin:{beforeFinalFence:({own})=>{own.finalCallbackEntered=true;own.finalMarkerReads=0;},afterCapturedMarker:({f,own})=>{if(!own.finalCallbackEntered||crossed)return;own.finalMarkerReads++;if(own.finalMarkerReads!==2)return;crossed=true;f.advance(window==='source'?60001:2000);}}});assert.equal(crossed,true);assert.equal(r.own.finalMarkerReads,2);assert.equal(r.own.adminPreflight,true);assert.equal(r.posts.length,0);assert.equal(r.marker.outcome.state,'SEND_UNKNOWN');assert.equal(r.errors.length,1);assert.equal(r.errors[0].code,window==='source'?'META_CUSTOMER_INBOX_LEASE_CHANGED':'META_CHANNEL_CONSUMPTION_RECOVERY_EXPIRED');assert.ok(r.own.graph.every(row=>row.inTransaction===0));
});

for(const credential of ['encryptedAccessToken','phoneNumberId'])test('legacy ADMIN readiness cannot reuse a changed '+credential+' for the captured reply',async()=>{
 let changed=false;const r=await composed({legacyAdmin:{afterGet:({f,own})=>{if(!own.graph.at(-1).path.endsWith('/phone_numbers'))return;changed=true;f.connection[credential]=credential==='encryptedAccessToken'?f.connection.encryptedAccessToken+'-rotated':'990000099';}}});assert.equal(changed,true);assert.equal(r.posts.length,0);assert.equal(r.errors.length,1);assert.equal(r.errors[0].code,credential==='phoneNumberId'?'WORKER_CHANNEL_PROOF_INTEGRITY':'META_CUSTOMER_OUTBOUND_CONTEXT_CHANGED');assert.equal(r.marker.outcome.state,'SEND_STARTED');assert.ok(r.own.graph.every(row=>row.inTransaction===0));
});

test('legacy ADMIN final transaction resolves the canonical principal before acquiring the outbound marker lock',async()=>{
 const r=await composed({legacyAdmin:{}});assert.equal(r.errors.length,0);assert.equal(r.posts.length,1);const finalQueries=r.intercepted.slice(r.own.graph.at(-1).sqlIndex),resolver=finalQueries.findIndex(row=>row.sql.startsWith('SELECT w.id,w."projectId",w.metadata,')),marker=finalQueries.findIndex(row=>row.sql.includes("provider='meta-customer-outbound-v1'")&&row.sql.includes('FOR UPDATE'));assert.ok(resolver>=0);assert.ok(marker>resolver);assert.equal(finalQueries[0].sql,'BEGIN');assert.equal(r.posts[0].inTransaction,1);assert.match(r.posts[0].lastSql,/clock_timestamp\(\) AS now/);
});
